// 05b — Gmail por ALIAS (plus addressing). Ejecución MANUAL: no hay disparador programado.
// Interruptores: con ambos en false el workflow no llama a Google ni al backend.
// LECTURA en true y INGESTA en false solo lista qué se procesaría (y a qué alias se asignaría), sin descargar adjuntos.
const AUTORIZAR_LECTURA_GMAIL = false;
const AUTORIZAR_INGESTA = false;

// IDENTIDAD OAuth del buzón (la cuenta que autorizó a n8n) y dirección de ENTREGA del alias: son cosas distintas.
// Sin estos datos el workflow se detiene antes de llamar a Google (los escribe n8n/tools/import-workflow.mjs).
const BUZON_AUTORIZADO = '';
const ALIAS_ENTREGA = '';
const REMITENTES_AUTORIZADOS = [];
// Etiqueta EXCLUSIVA del alias (la aplica un filtro de Gmail) y prefijo de las etiquetas de alias.
const ETIQUETA = 'nh-camila';
const PREFIJO_ETIQUETAS = 'nh-';
// Solo mensajes recientes: nunca el histórico del buzón.
const VENTANA = '2d';

// Solo metadatos de partes: el cuerpo del correo nunca se descarga.
const part = 'partId,mimeType,filename,body(attachmentId,size)';
const nest = (depth) => (depth === 0 ? part : part + ',parts(' + nest(depth - 1) + ')');

return [{ json: {
  readAuthorized: AUTORIZAR_LECTURA_GMAIL === true,
  ingestAuthorized: AUTORIZAR_LECTURA_GMAIL === true && AUTORIZAR_INGESTA === true,
  scheduled: false,
  mailbox: BUZON_AUTORIZADO.trim().toLowerCase(),
  alias: ALIAS_ENTREGA.trim().toLowerCase(),
  allowedSenders: REMITENTES_AUTORIZADOS.map((s) => s.trim().toLowerCase()),
  label: ETIQUETA,
  labelPrefix: PREFIJO_ETIQUETAS,
  window: VENTANA,
  apiBase: 'https://notihouse-pal-api.onrender.com/api/v1',
  gmailBase: 'https://gmail.googleapis.com',
  maxMessages: 5,
  maxAttachmentsPerMessage: 5,
  // Mismo máximo inicial del backend para un PDF, que sigue siendo quien decide.
  maxPdfBytes: 10 * 1024 * 1024,
  messageFields: 'id,internalDate,labelIds,payload(headers(name,value),' + nest(4) + ')',
} }];

const cfg = $('Configuracion').first().json;
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email.test(cfg.mailbox)) throw new Error('Falta BUZON_AUTORIZADO (identidad OAuth): no se llamó a Google.');
if (!email.test(cfg.alias)) throw new Error('Falta ALIAS_ENTREGA: no se llamó a Google.');
// El alias debe ser «buzón+etiqueta@dominio» de ESA misma cuenta, y distinto de la dirección general.
const split = (a) => { const [local, domain] = a.split('@'); const plus = local.indexOf('+'); return { base: (plus === -1 ? local : local.slice(0, plus)).replace(/\./g, ''), tag: plus === -1 ? '' : local.slice(plus + 1), domain }; };
const mb = split(cfg.mailbox); const al = split(cfg.alias);
if (al.tag === '' || al.base !== mb.base || al.domain !== mb.domain) throw new Error('ALIAS_ENTREGA no es un alias (buzón+etiqueta@dominio) del buzón autorizado: no se llamó a Google.');
if (cfg.allowedSenders.length === 0 || !cfg.allowedSenders.every((s) => email.test(s))) {
  throw new Error('Falta REMITENTES_AUTORIZADOS: no se llamó a Google.');
}
if (!/^[a-z0-9-]+$/.test(cfg.label) || !cfg.label.startsWith(cfg.labelPrefix)) throw new Error('La etiqueta no es válida o no usa el prefijo de alias: no se llamó a Google.');
if (!/^[1-9][0-9]?d$/.test(cfg.window)) throw new Error('La ventana de antigüedad no es válida: no se llamó a Google.');
// Nunca toda la bandeja: etiqueta exclusiva, adjunto PDF, remitente y antigüedad, todos obligatorios.
const query = 'label:' + cfg.label + ' has:attachment filename:pdf newer_than:' + cfg.window + ' from:(' + cfg.allowedSenders.join(' OR ') + ')';
return [{ json: { query } }];

// Mensaje fijo: el error original no se copia para no arrastrar datos de la solicitud.
const detail = $input.first().json.error ?? $input.first().json;
const code = Number(detail?.httpCode ?? /^(\d{3})\b/.exec(String(detail?.cause?.message ?? detail?.message ?? ''))?.[1] ?? 0);
const needsReconnect = /reconnected|invalid_grant/i.test(String(detail?.message ?? '') + String(detail?.description ?? '') + String(detail?.cause?.message ?? ''));
const reason = needsReconnect ? 'la credencial debe reconectarse en n8n: su autorización se revocó o venció (en modo Testing de Google, a los 7 días)'
  : code === 401 ? 'la credencial OAuth fue rechazada o revocada (401)'
  : code === 403 ? 'la credencial no tiene permiso de lectura, o se alcanzó un límite (403)'
    : code === 429 ? 'se alcanzó un límite de Gmail (429)'
      : 'Gmail no respondió correctamente' + (code ? ' (HTTP ' + code + ')' : '');
throw new Error('Gmail: ' + reason + '. No se registró nada; reejecutar es seguro.');

const cfg = $('Configuracion').first().json;
const actual = String($input.first().json.emailAddress ?? '').trim().toLowerCase();
if (actual === '' || actual !== cfg.mailbox) {
  throw new Error('La credencial OAuth no corresponde al buzón autorizado. No se leyó ningún mensaje.');
}
return [{ json: { mailbox: actual, query: $('Validar configuracion').first().json.query } }];

// 05b: resolución ESTRICTA del destinatario (la misma función que prueban n8n/tests/gmail-alias.test.mjs).
function resolveDelivery(input) {
  const reject = (reason) => ({ ok: false, reason });
  const headers = Array.isArray(input?.headers) ? input.headers : [];
  const labelIds = Array.isArray(input?.labelIds) ? input.labelIds : [];
  const labelNames = input?.labelNames && typeof input.labelNames === 'object' ? input.labelNames : {};

  // Dirección → { base, tag, domain, full }. Gmail ignora los puntos y las mayúsculas de la parte local y
  // trata googlemail.com como gmail.com; `tag` es null sin «+», '' con «+» vacío (malformado).
  const canon = (raw) => {
    const m = /^([a-z0-9._%+-]+)@([a-z0-9.-]+)$/.exec(String(raw ?? '').trim().toLowerCase());
    if (!m) return null;
    const domain = m[2] === 'googlemail.com' ? 'gmail.com' : m[2];
    const plus = m[1].indexOf('+');
    const local = plus === -1 ? m[1] : m[1].slice(0, plus);
    const base = domain === 'gmail.com' ? local.replace(/\./g, '') : local;
    const tag = plus === -1 ? null : m[1].slice(plus + 1);
    return { base, tag, domain, full: `${base}${tag === null ? '' : `+${tag}`}@${domain}` };
  };
  const addressesIn = (value) => (String(value ?? '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/g) ?? []).map(canon).filter(Boolean);

  const expected = canon(input?.expectedAlias);
  if (!expected || !expected.tag) return reject('configuracion_invalida');
  const expectedLabel = String(input?.expectedLabel ?? '');
  const labelPrefix = String(input?.labelPrefix ?? '');
  if (!expectedLabel) return reject('configuracion_invalida');
  const isOurs = (a) => a.base === expected.base && a.domain === expected.domain;
  const named = (name) => headers.filter((h) => String(h?.name ?? '').toLowerCase() === name);

  // 1) Cabeceras que no pueden repetirse (RFC 5322): una repetición es una señal de manipulación.
  if (named('to').length > 1 || named('cc').length > 1) return reject('encabezados_duplicados');

  // 2) Primer Delivered-To: lo pone Gmail; debe existir y ser una única dirección de ESTA cuenta, con alias.
  const delivered = named('delivered-to');
  if (delivered.length === 0) return reject('sin_delivered_to');
  const first = addressesIn(delivered[0].value);
  if (first.length !== 1 || !isOurs(first[0])) return reject('delivered_to_no_propio');
  if (first[0].tag === null) return reject('direccion_general');
  if (first[0].tag === '') return reject('alias_malformado');
  if (first[0].full !== expected.full) return reject('alias_distinto');
  // Otros Delivered-To de nuestra cuenta con otra dirección: contradictorio. Los ajenos (reenvíos) se ignoran.
  for (const h of delivered.slice(1)) {
    for (const a of addressesIn(h.value)) if (isOurs(a) && a.full !== expected.full) return reject('delivered_to_contradictorio');
  }

  // 3) To/Cc: ninguna otra dirección de la cuenta (ni la general ni otro alias). Si el alias esperado no
  //    aparece (Bcc), basta con las dos señales independientes de arriba y de la etiqueta.
  let inRecipients = false;
  for (const h of [...named('to'), ...named('cc')]) {
    for (const a of addressesIn(h.value)) {
      if (!isOurs(a)) continue;
      if (a.full !== expected.full) return reject('destinatarios_contradictorios');
      inRecipients = true;
    }
  }

  // 4) Etiquetas: debe estar la esperada y NINGUNA otra del mismo prefijo (nh-*).
  const names = labelIds.map((id) => labelNames[id]).filter((n) => typeof n === 'string');
  if (!names.includes(expectedLabel)) return reject('etiqueta_ausente');
  if (labelPrefix && names.filter((n) => n.startsWith(labelPrefix)).length !== 1) return reject('etiqueta_incoherente');

  return { ok: true, mailbox: expected.full, evidencia: { deliveredTo: true, etiqueta: expectedLabel, enDestinatarios: inRecipients } };
}
const cfg = $('Configuracion').first().json;
const pending = $('Preparar mensajes').all();
const labelNames = Object.fromEntries(($('Etiquetas de Gmail').first().json.labels ?? []).map((l) => [l.id, l.name]));

const header = (msg, name) => (msg.payload?.headers ?? []).find((h) => String(h.name).toLowerCase() === name)?.value ?? '';
const senderOf = (from) => (/<([^<>]+)>\s*$/.exec(from)?.[1] ?? from).trim().toLowerCase();
// No se entra en mensajes reenviados: lo que traen dentro está fuera del alcance.
function collect(part, found = []) {
  if (part.filename) found.push(part);
  if (part.mimeType !== 'message/rfc822') for (const child of part.parts ?? []) collect(child, found);
  return found;
}

const out = [];
$input.all().forEach((item, i) => {
  const messageId = pending[i].json.messageId;
  const msg = item.json.body;
  if (item.json.statusCode !== 200 || !msg?.payload) {
    out.push({ json: { messageId, outcome: 'error_gmail', httpStatus: item.json.statusCode ?? null } });
    return;
  }
  const from = header(msg, 'from');
  const base = { messageId, receivedAt: new Date(Number(msg.internalDate)).toISOString() };
  if (!cfg.allowedSenders.includes(senderOf(from))) {
    out.push({ json: { ...base, outcome: 'remitente_no_autorizado' } });
    return;
  }
  // Destinatario: dos señales independientes y coherentes, o rechazo sin efectos (ni documento, ni caso, ni trabajo).
  const delivery = resolveDelivery({ headers: msg.payload?.headers ?? [], labelIds: msg.labelIds ?? [], labelNames, expectedAlias: cfg.alias, expectedLabel: cfg.label, labelPrefix: cfg.labelPrefix });
  if (!delivery.ok) {
    out.push({ json: { ...base, outcome: 'destinatario_rechazado', motivo: delivery.reason } });
    return;
  }
  const seen = { ...base, from, subject: header(msg, 'subject'), deliveryMailbox: delivery.mailbox };
  const parts = collect(msg.payload);
  if (parts.length === 0) out.push({ json: { ...seen, outcome: 'sin_adjuntos' } });
  let accepted = 0;
  for (const p of parts) {
    const a = { ...seen, partId: p.partId, fileName: p.filename, mimeType: p.mimeType, size: p.body?.size ?? 0 };
    const isPdf = /\.pdf$/i.test(p.filename) && String(p.mimeType).toLowerCase() === 'application/pdf';
    if (!isPdf) out.push({ json: { ...a, outcome: 'tipo_no_admitido' } });
    else if (!p.body?.attachmentId) out.push({ json: { ...a, outcome: 'sin_identificador' } });
    else if (a.size > cfg.maxPdfBytes) out.push({ json: { ...a, outcome: 'demasiado_grande' } });
    else if (accepted >= cfg.maxAttachmentsPerMessage) out.push({ json: { ...a, outcome: 'limite_de_adjuntos' } });
    else {
      accepted += 1;
      out.push({ json: cfg.ingestAuthorized
        ? { ...a, attachmentId: p.body.attachmentId, download: true }
        : { ...a, outcome: 'pendiente_de_autorizacion' } });
    }
  }
});
return out;

const wanted = $('Extraer adjuntos').all().filter((x) => x.json.download);
return $input.all().map((item, i) => {
  const { attachmentId, download, deliveryMailbox, ...source } = wanted[i].json;
  const data = item.json.body?.data;
  if (item.json.statusCode !== 200 || typeof data !== 'string') {
    return { json: { ...source, outcome: 'error_gmail', httpStatus: item.json.statusCode ?? null } };
  }
  const base64 = data.replace(/-/g, '+').replace(/_/g, '/');
  const bytes = Buffer.from(base64, 'base64');
  if (bytes.length !== source.size) {
    return { json: { ...source, outcome: 'error_gmail', httpStatus: null } };
  }
  return {
    json: { ...source, decoded: true, mailbox: deliveryMailbox, runId: String($execution.id ?? 'manual').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64) },
    binary: { data: { data: bytes.toString('base64'), mimeType: 'application/pdf', fileName: source.fileName, fileExtension: 'pdf' } },
  };
});

const sent = $('Decodificar').all().filter((x) => x.json.decoded);
const OUTCOME = { 201: 'registrado', 200: 'ya_registrado', 400: 'rechazado', 413: 'rechazado', 415: 'rechazado', 401: 'token_rechazado', 403: 'buzon_no_vinculado', 409: 'conflicto' };
return $input.all().map((item, i) => {
  const { decoded, runId, mailbox, ...source } = sent[i].json;
  const status = item.json.statusCode ?? null;
  const body = status === 200 || status === 201 ? item.json.body : {};
  return { json: {
    ...source,
    outcome: OUTCOME[status] ?? 'error_temporal',
    httpStatus: status,
    documentId: body.documentId,
    caseId: body.caseId,
    duplicateContent: body.duplicateContent,
  } };
});

const cfg = $('Configuracion').first().json;
const items = $input.all().map((x) => x.json);
const counts = {};
for (const x of items) counts[x.outcome] = (counts[x.outcome] ?? 0) + 1;
// Remitente y asunto solo se muestran en la revisión previa, y nunca a los no autorizados.
const detail = items.map(({ attachmentId, download, ...x }) => (cfg.ingestAuthorized ? { ...x, from: undefined, subject: undefined } : x));
const moreMessages = Boolean($('Listar mensajes').first().json.nextPageToken);
const FAILURES = ['error_gmail', 'error_temporal', 'token_rechazado', 'buzon_no_vinculado', 'conflicto'];
const failed = FAILURES.filter((f) => counts[f]);
if (failed.length > 0) {
  throw new Error('Recepción incompleta: ' + failed.map((f) => f + '=' + counts[f]).join(', ') + '. Reejecutar es seguro: lo ya registrado no se duplica.');
}
return [{ json: { modo: cfg.ingestAuthorized ? 'ingesta' : 'solo_revision', conteo: counts, hayMasMensajes: moreMessages, detalle: detail } }];
